mapper.select:
SELECT EMP_ID AS userId , EMP_NM AS userNm , DEPT_NM AS deptNm , JOB_ROLE AS jobRole , POSITION_NM AS positionNm , CAREER_YEARS AS careerYears , 0 AS remainingMM , 0 AS currentLoad , DATE_FORMAT(JOIN_DT, '%Y-%m-%d') AS joinDt , IN_OFFICE AS useYn FROM TB_EMP WHERE DEL_YN = 'N'
AND EMP_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY DEPT_NM ASC, EMP_NM ASC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
