    EMP_ID, EMP_NM, DEPT_NM, JOB_ROLE, POSITION_NM, 
    CAREER_YEARS, JOB_FIELD, JOIN_DT, IN_OFFICE, SKILL_DESC
) VALUES (
    #{userId}, #{userNm}, #{deptNm}, #{jobRole}, #{positionNm}, 
    #{careerYears}, #{jobField}, #{joinDt}, #{useYn}, #{skillDesc}
)

mapper.update:
UPDATE TB_EMP SET
      EMP_NM         = #{userNm}
    , DEPT_NM        = #{deptNm}
    , JOB_ROLE       = #{jobRole}
    , POSITION_NM    = #{positionNm}
    , CAREER_YEARS   = #{careerYears}
    , JOB_FIELD      = #{jobField}
    , IN_OFFICE      = #{useYn}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , SKILL_DESC     = #{skillDesc}
    , JOIN_DT = IFNULL(JOIN_DT, NULLIF(#{joinDt}, ''))
WHERE EMP_ID = #{userId}

UPDATE TB_EMP SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE EMP_ID = #{userId}

UPDATE TB_EMP
   SET ATCH_FILE_ID = #{atchFileId}
 WHERE EMP_ID = #{userId}
